package com.drogaria.backend.service;
import com.drogaria.backend.dto.PagamentoResponse; import com.drogaria.backend.entity.Pagamento; import com.drogaria.backend.exception.ApiException; import com.drogaria.backend.repository.PagamentoRepository; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service;
@Service public class PagamentoService { private final PagamentoRepository r; public PagamentoService(PagamentoRepository r){this.r=r;} public PagamentoResponse buscar(Integer id){return new PagamentoResponse(r.findById(id).orElseThrow(()->new ApiException("Pagamento nao encontrado",HttpStatus.NOT_FOUND)));} public PagamentoResponse pedido(Integer id){return new PagamentoResponse(r.findByPedidoId(id).orElseThrow(()->new ApiException("Pagamento nao encontrado",HttpStatus.NOT_FOUND)));} public PagamentoResponse status(Integer id,String status){Pagamento p=r.findById(id).orElseThrow(()->new ApiException("Pagamento nao encontrado",HttpStatus.NOT_FOUND));p.setStatus(status);return new PagamentoResponse(r.save(p));} }